const item = $input.first().json;
const body = item.body || item;
function normalizePhone(phone) {
  if (!phone) return '';
  const d = String(phone).replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d.startsWith('1')) return '+' + d;
  return d ? '+1' + d : '';
}
const raw = [body.project_type, body.service, body.form_name, body.message].join(' ').toLowerCase();
let project_type = 'multi';
if (raw.includes('cuisine')) project_type = 'cuisine';
else if (raw.includes('salle') || raw.includes('bain')) project_type = 'salle_de_bain';
else if (raw.includes('sous')) project_type = 'sous_sol';
else if (raw.includes('patio') || raw.includes('terrasse')) project_type = 'patio';
else if (raw.includes('agrand')) project_type = 'agrandissement';
else if (raw.includes('extérieur') || raw.includes('exterieur') || raw.includes('toiture')) project_type = 'exterieur';
const nowStr = new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' });
const toronto = new Date(nowStr);
const hour = toronto.getHours();
const day = toronto.getDay();
const isBusinessHours = day >= 1 && day <= 6 && hour >= 9 && hour < 19;
return [{ json: {
  ...body,
  first_name: body.first_name || '',
  last_name: body.last_name || '',
  phone: normalizePhone(body.phone || body.mobile),
  email: body.email || '',
  lead_city: body.lead_city || body.city || '',
  project_type: body.project_type || project_type,
  budget_range: body.budget_range || '',
  property_type: body.property_type || '',
  isBusinessHours,
  upload_url: 'https://soumissionentrepreneurs.com/'
}}];

const b = $('2 Projet + Tel + Heures').first().json;
const token = '{{HAIDLY_WEBHOOK_TOKEN}}';
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/haidly/lead',
  headers: { 'X-Haidly-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: {
    first_name: b.first_name,
    last_name: b.last_name,
    phone: b.phone,
    email: b.email,
    city: b.lead_city,
    project_type: b.project_type,
    budget_range: b.budget_range,
    property_type: b.property_type,
    source: b.source || (b.form_id || b.page_id ? 'meta_lead_ads' : 'soumissionentrepreneurs'),
    form_id: b.form_id || b.leadgen_form_id || '',
    page_id: b.page_id || b.facebook_page_id || ''
  },
  json: true,
});
return [{ json: { ...b, ...res } }];

const b = $('3 Odoo Create Lead').first().json;
const phone = b.phone;
if (!phone) return [{ json: b }];
const sid = '{{TWILIO_ACCOUNT_SID}}';
const auth = Buffer.from(sid + ':{{TWILIO_AUTH_TOKEN}}').toString('base64');
const first = b.first_name || 'Bonjour';
const emoji = { cuisine: '🍳', salle_de_bain: '🛁', sous_sol: '🏠', patio: '☀️' }[b.project_type] || '🏠';
const msg = `${first}! ${emoji} C'est Haidly de SoumissionEntrepreneurs. Envoyez vos photos ici: https://soumissionentrepreneurs.com/ — Plans 3D GRATUITS, sans frais!`;
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
  headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent('+15817058118')}&Body=${encodeURIComponent(msg)}`,
});
return [{ json: { ...b, sms_sent: true } }];

const lead = $('3 Odoo Create Lead').first().json;
const prep = $('2 Projet + Tel + Heures').first().json;
const apiKey = '{{ELEVENLABS_API_KEY}}';
const agentId = lead.elevenlabs_agent_id_haidly || '';
const phId = lead.elevenlabs_phone_number_id || '';
if (!agentId || !phId || !prep.phone) {
  return [{ json: { ...lead, call_skipped: true, reason: 'missing_agent_or_phone' } }];
}
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call',
  headers: { 'xi-api-key': apiKey, 'Content-Type': 'application/json' },
  body: {
    agent_id: agentId,
    agent_phone_number_id: phId,
    to_number: prep.phone,
    telephony_call_config: { ringing_timeout_secs: 25 },
    conversation_initiation_client_data: {
      dynamic_variables: {
        lead_name: prep.first_name || 'there',
        project_type: prep.project_type,
        city: prep.lead_city,
        budget_range: prep.budget_range || '',
        property_type: prep.property_type || '',
        lead_id_odoo: String(lead.lead_id || '')
      }
    }
  },
  json: true,
});
return [{ json: { ...lead, ...res, call_started: true } }];

const lead = $('3 Odoo Create Lead').first().json;
const prep = $('2 Projet + Tel + Heures').first().json;
if (!lead.lead_id) return [];
const token = '{{HAIDLY_WEBHOOK_TOKEN}}';
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/haidly/lead/update',
  headers: { 'X-Haidly-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: { lead_id: lead.lead_id, next_action: 'Appel matin programmé 9h Toronto (lead hors heures)' },
  json: true,
});
return [{ json: {
  pipeline: 'haidly',
  lead_id: lead.lead_id,
  phone: prep.phone || lead.phone,
  first_name: prep.first_name,
  project_type: lead.project_type,
  city: lead.city,
  budget_range: prep.budget_range || '',
  property_type: prep.property_type || '',
  agent_id: lead.elevenlabs_agent_id_haidly || lead.agent_id || '',
  elevenlabs_phone_number_id: lead.elevenlabs_phone_number_id || ''
}}];
